    // Whole words only: do not alter equipment names such as the Chalice prick action or dictionary.
    private static final Pattern ENGLISH = Pattern.compile("\\b(?:fuck\\w*|shit\\w*|bitch\\w*|bastard\\w*|asshole\\w*|dick(?:s|heads?)?|piss\\w*|cunt\\w*|goddamn\\w*|wank\\w*|twat\\w*|motherfuck\\w*|arse(?:s|holes?)?|slut(?:s)?|whore(?:s)?|damn(?:ed|ing)?|dammit|hell|crap|ass(?:es)?|jackass(?:es)?|cock(?:s|suckers?)?|bollocks|bugger(?:s|ed|ing)?|douche(?:bags?)?|faggot(?:s)?|retard(?:s|ed)?)\\b",Pattern.CASE_INSENSITIVE);
    private AuthoredLanguage() {}
    public static String select(String authoredTemplate, boolean adult) {
        if(adult || authoredTemplate==null)return authoredTemplate;
        String clean=CLEAN.get(authoredTemplate);
        return clean==null ? authoredTemplate : clean;
    }
    /** Only for English developer-authored prose, before user values are substituted. */
    public static String english(String authoredTemplate, boolean adult) {
        String selected=select(authoredTemplate,adult);
        if(adult || selected==null)return selected;
        Matcher words=ENGLISH.matcher(selected);StringBuffer clean=new StringBuffer();
        while(words.find()) {
            String replacement=words.group().equals(words.group().toUpperCase(java.util.Locale.ROOT)) ? "SERIOUSLY" : "seriously";
            words.appendReplacement(clean,Matcher.quoteReplacement(replacement));
        }
        words.appendTail(clean);return clean.toString();
    }
    public static boolean containsEnglishProfanity(String text){return text!=null && ENGLISH.matcher(text).find();}
    public static Map<String,String> alternatives(){return CLEAN;}
